// Общее для #0651d2 (PR #200): плавающие WhatsApp/נגישות и мобильное меню «תפריט». Прод, только чтение.
// WhatsApp поддержки ищем ТОЛЬКО по aria-label («שירות הלקוחות») — тот же номер есть у карточек объявлений.
// נגישות — CSS по aria-label: при открытом Radix Sheet фон aria-hidden, getByRole её не видит.
// WhatsApp НЕ нажимаем: касание проверяем document.elementFromPoint.
import { expect, Locator, Page } from '@playwright/test';
import { LOAD } from '../html-rtl-dir/rtl-dir.helpers';

export const MENU = 'תפריט';
export const SIZE = 44; // #96f55c: 44×44 на мобайле

export const whatsapp = (page: Page) => page.locator('a[aria-label*="שירות הלקוחות"]');
export const a11yButton = (page: Page) => page.locator('button[aria-label="פתח תפריט נגישות"]');
export const menuButton = (page: Page) =>
  page.getByRole('banner', { includeHidden: true }).getByRole('button', { name: MENU, exact: true, includeHidden: true });
export const menuDialog = (page: Page) =>
  page.getByRole('dialog').filter({ has: page.getByRole('heading', { name: MENU, exact: true }) });

/** Кнопка внизу меню по точному тексту (последнее совпадение — блок кнопок под разделителем). */
export const menuAction = (menu: Locator, text: string) => menu.getByText(text, { exact: true }).last();

export async function openMenu(page: Page) {
  await menuButton(page).click();
  const menu = menuDialog(page);
  await expect(menu, 'открыто меню «תפריט»').toBeVisible(LOAD);
  return menu;
}

/** Плавающие кнопки скрыты (display:none / вне дерева / невидимы). */
export async function expectFloatingHidden(page: Page, where: string) {
  await expect(whatsapp(page), `${where}: плавающий WhatsApp скрыт`).toBeHidden();
  await expect(a11yButton(page), `${where}: плавающая נגישות скрыта`).toBeHidden();
}

/** Центр элемента — сам элемент (касание доходит). */
async function centerHitsSelf(loc: Locator) {
  return loc.evaluate((el) => {
    const r = el.getBoundingClientRect();
    const hit = document.elementFromPoint(r.left + r.width / 2, r.top + r.height / 2);
    return !!hit && el.contains(hit);
  });
}

/** Плавающие кнопки видны, 44×44 ±1, WhatsApp над נגישות с тем же левым краем, центр получает касание. */
export async function expectFloatingBack(page: Page, where: string) {
  const wa = whatsapp(page);
  const acc = a11yButton(page);
  await expect(wa, `${where}: плавающий WhatsApp виден`).toBeVisible(LOAD);
  await expect(acc, `${where}: плавающая נגישות видна`).toBeVisible(LOAD);
  const box = async (l: Locator) => (await l.boundingBox())!;
  for (const [name, l] of [['WhatsApp', wa], ['נגישות', acc]] as const) {
    // ждём конца анимации появления: размер устоялся в пределах ±1 от 44
    await expect
      .poll(async () => { const b = await box(l); return Math.max(Math.abs(b.width - SIZE), Math.abs(b.height - SIZE)) <= 1; }, { message: `${where}: ${name} 44×44`, ...LOAD })
      .toBe(true);
    const b = await box(l);
    expect(Math.abs(b.width - SIZE), `${where}: ${name} ширина ${b.width} ≈ ${SIZE}`).toBeLessThanOrEqual(1);
    expect(Math.abs(b.height - SIZE), `${where}: ${name} высота ${b.height} ≈ ${SIZE}`).toBeLessThanOrEqual(1);
    expect(await centerHitsSelf(l), `${where}: касание в центр ${name} доходит до самой кнопки`).toBe(true);
  }
  const w = await box(wa);
  const a = await box(acc);
  expect(w.y + w.height, `${where}: WhatsApp над נגישות`).toBeLessThanOrEqual(a.y + 1);
  expect(Math.abs(w.x - a.x), `${where}: одинаковый левый край (#062b41)`).toBeLessThanOrEqual(2);
}

export type Hit = { point: string; x: number; y: number; inViewport: boolean; ok: boolean; hit: string | null };

/** Hit-test кнопки меню: левый край (left+4) и центр по высоте; попадание — сама кнопка (a/button) или её потомок. */
export async function hitTest(target: Locator): Promise<Hit[]> {
  await target.scrollIntoViewIfNeeded();
  return target.evaluate((el) => {
    const btn = (el.closest('a,button') ?? el) as HTMLElement;
    const r = btn.getBoundingClientRect();
    const y = r.top + r.height / 2;
    return [
      { point: 'левый край', x: r.left + 4 },
      { point: 'центр', x: r.left + r.width / 2 },
    ].map(({ point, x }) => {
      const hit = document.elementFromPoint(x, y);
      return {
        point,
        x: Math.round(x),
        y: Math.round(y),
        inViewport: y >= 0 && y <= window.innerHeight && x >= 0 && x <= window.innerWidth,
        ok: !!hit && btn.contains(hit),
        hit: hit ? hit.outerHTML.slice(0, 160) : null,
      };
    });
  });
}
